/**
 * The key segments a share prefix names. Mirrors the server's refusals, so a
 * bad prefix fails here instead of being denied without a prompt.
 *
 * @param {unknown} prefix
 * @returns {string[]}
 */
export function kvSharePrefixSegments(prefix: unknown): string[];
/**
 * The delegation a `'kvShare'` request asks for: this app sharing a region of
 * the data it keeps for this user.
 *
 * @param {import('../../index.js').Puter} puter
 * @param {Record<string, any>} whoami
 * @param {Record<string, unknown>} details
 * @returns {string}
 */
export function kvShareRequestPermission(puter: import("../../index.js").Puter, whoami: Record<string, any>, details: Record<string, unknown>): string;
export type PermsKvShareAccess = import("./types.js").PermsKvShareAccess;
